import { useState, useEffect } from 'react'
import useAppStore from '../store/appStore'

const IN2_TO_CM2 = 6.4516
const IN4_TO_CM4 = 41.623
const IN3_TO_CM3 = 16.387

export default function WShape() {
  const [shapes,   setShapes]   = useState([])
  const [query,    setQuery]    = useState('')
  const [selected, setSelected] = useState(null)
  const [error,    setError]    = useState(null)
  const [unit,     setUnit]     = useState('both')

  // H-shapes for cross-reference
  const [hShapes, setHShapes] = useState([])

  const { setActiveView, setPendingHShape, pendingWShape, clearPendingWShape } = useAppStore()
  const dataBase = window.location.pathname.replace(/\/$/, '') + '/'

  useEffect(() => {
    fetch(`${dataBase}data/wShapes.json`)
      .then(r => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json() })
      .then(data => setShapes([...data].sort((a, b) => {
        const sa = parseInt(a.label_in?.match(/W(\d+)/)?.[1] || 0)
        const sb = parseInt(b.label_in?.match(/W(\d+)/)?.[1] || 0)
        return sa !== sb ? sa - sb : a.W_lbft - b.W_lbft
      })))
      .catch(e => setError(`W-Shape data load failed: ${e.message}`))

    fetch(`${dataBase}data/hShapes.json`).then(r => r.json()).then(setHShapes).catch(() => {})
  }, [])

  // Auto-select shape when navigated from H-Shape cross-reference
  useEffect(() => {
    if (shapes.length && pendingWShape) {
      const match = shapes.find(s => s.label_in === pendingWShape.label_in)
      if (match) setSelected(match)
      clearPendingWShape()
    }
  }, [shapes, pendingWShape])

  // Group by depth series (W10, W12, ...)
  const groups = {}
  const filtered = query.length >= 2
    ? shapes.filter(s =>
        s.label_in?.toLowerCase().includes(query.toLowerCase()) ||
        s.label_mm?.toLowerCase().includes(query.toLowerCase())
      )
    : shapes
  filtered.forEach(s => {
    const depth = s.label_in?.match(/W(\d+)/)?.[1]
    const key = depth ? `W${depth}` : 'Other'
    if (!groups[key]) groups[key] = []
    groups[key].push(s)
  })

  const similarH = selected ? findSimilarH(selected, hShapes) : []

  function gotoHShape(h) {
    setPendingHShape(h)
    setActiveView('hs-shape')
  }

  return (
    <div>
      <h3 style={titleStyle}>W-SHAPE (AISC)</h3>
      <div style={{ display: 'flex', gap: 12, marginBottom: 16, flexWrap: 'wrap', alignItems: 'center' }}>
        <input placeholder="Search (e.g. W14, W300)"
          value={query} onChange={e => setQuery(e.target.value)}
          style={{ ...inputStyle, width: 240 }} />
        <div style={{ display: 'flex', gap: 6 }}>
          {[{ id: 'both', label: 'US + SI' }, { id: 'us', label: 'US (in)' }, { id: 'si', label: 'SI (mm)' }].map(u => (
            <button key={u.id} onClick={() => setUnit(u.id)} style={{
              padding: '4px 12px', borderRadius: 5, fontSize: 11, fontWeight: 600, cursor: 'pointer',
              border: '1px solid var(--bd-subtle)',
              background: unit === u.id ? 'var(--ac-main)' : 'var(--bg-card)',
              color: unit === u.id ? '#000' : 'var(--tx-secondary)',
            }}>{u.label}</button>
          ))}
        </div>
      </div>

      <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start' }}>
        {/* Left: series list */}
        <div style={{ width: 200, flexShrink: 0, overflowY: 'auto', maxHeight: 600 }}>
          {Object.entries(groups).map(([series, items]) => (
            <div key={series} style={{ marginBottom: 6 }}>
              <div style={seriesHead}>{series}</div>
              {items.map(s => (
                <button key={s.label_in} onClick={() => setSelected(s)} style={{
                  display: 'block', width: '100%', textAlign: 'left',
                  padding: '4px 10px', borderRadius: 4, fontSize: 11,
                  cursor: 'pointer', border: 'none', marginBottom: 2,
                  background: selected?.label_in === s.label_in ? 'var(--ac-main)' : 'var(--bg-card)',
                  color: selected?.label_in === s.label_in ? '#000' : 'var(--tx-secondary)',
                  borderLeft: `3px solid ${selected?.label_in === s.label_in ? '#000' : 'transparent'}`,
                }}>
                  <span style={{ fontWeight: 600 }}>{s.label_in}</span>
                  <span style={{ marginLeft: 5, opacity: 0.65, fontSize: 10 }}>{s.W_lbft}#</span>
                </button>
              ))}
            </div>
          ))}
        </div>

        {/* Right: properties */}
        {selected ? (
          <div style={{ flex: 1 }}>
            <WShapeDetail s={selected} unit={unit} />

            {/* Cross-reference: similar KS H-shapes by Sx */}
            {similarH.length > 0 && (
              <div style={{ marginTop: 16 }}>
                <SectionHeader>Similar KS H-Shapes (Sx ≈ {(selected.Sx * IN3_TO_CM3).toFixed(0)} cm³ ± 20%)</SectionHeader>
                <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                  {similarH.map(h => (
                    <button key={h.name} onClick={() => gotoHShape(h)} style={{
                      padding: '4px 10px', borderRadius: 5,
                      fontSize: 11, cursor: 'pointer',
                      background: 'var(--bg-card)', border: '1px solid var(--bd-accent)',
                      color: 'var(--ac-main)',
                    }}>
                      {h.name}
                      <span style={{ fontSize: 10, color: 'var(--tx-muted)', marginLeft: 4 }}>
                        Sx={h.Sx} cm³
                      </span>
                    </button>
                  ))}
                </div>
                <p style={{ fontSize: 10, color: 'var(--tx-muted)', marginTop: 6 }}>
                  Click to navigate to H-Shape view
                </p>
              </div>
            )}
          </div>
        ) : (
          <div style={{ flex: 1, ...hint }}>← Select a shape from the list to view properties</div>
        )}
      </div>

      {error && <p style={{ color: 'var(--val-warn)', fontSize: 13, marginTop: 12 }}>⚠ {error}</p>}
    </div>
  )
}

function findSimilarH(wShape, hShapes) {
  if (!hShapes?.length) return []
  const Sx_cm3 = wShape.Sx * IN3_TO_CM3
  return hShapes
    .filter(h => Math.abs(h.Sx - Sx_cm3) / Sx_cm3 <= 0.20)
    .sort((a, b) => Math.abs(a.Sx - Sx_cm3) - Math.abs(b.Sx - Sx_cm3))
    .slice(0, 8)
}

function WShapeDetail({ s, unit }) {
  const showUS = unit === 'us' || unit === 'both'
  const showSI = unit === 'si' || unit === 'both'
  const W_kgm  = s.W_kgm ?? (s.W_lbft * 1.488).toFixed(1)

  return (
    <div>
      <h4 style={{ fontSize: 14, fontWeight: 700, color: 'var(--ac-main)', marginBottom: 4 }}>
        {s.label_in}
        {s.label_mm && <span style={{ fontSize: 11, color: 'var(--tx-muted)', marginLeft: 10 }}>{s.label_mm}</span>}
      </h4>
      <p style={{ fontSize: 12, color: 'var(--tx-secondary)', marginBottom: 12 }}>
        {s.W_lbft} lb/ft &nbsp;|&nbsp; {W_kgm} kg/m
      </p>
      <div style={{ overflowX: 'auto' }}>
        <table style={{ borderCollapse: 'collapse', fontSize: 12, width: '100%', maxWidth: 560 }}>
          <thead>
            <tr>
              <th style={th}>Property</th>
              {showUS && <th style={th}>US Units</th>}
              {showSI && <th style={th}>SI Units</th>}
            </tr>
          </thead>
          <tbody>
            {[
              { label: 'd — Depth',            us: `${s.d} in`,   si: `${(s.d*25.4).toFixed(1)} mm` },
              { label: 'bf — Flange Width',    us: `${s.bf} in`,  si: `${(s.bf*25.4).toFixed(1)} mm` },
              { label: 'tw — Web Thickness',   us: `${s.tw} in`,  si: `${(s.tw*25.4).toFixed(1)} mm` },
              { label: 'tf — Flange Thickness',us: `${s.tf} in`,  si: `${(s.tf*25.4).toFixed(1)} mm` },
              { label: 'A — Area',              us: `${s.A} in²`,  si: `${(s.A*IN2_TO_CM2).toFixed(1)} cm²` },
              { label: 'Ix — Strong-Axis I',   us: `${s.Ix} in⁴`, si: `${(s.Ix*IN4_TO_CM4).toFixed(0)} cm⁴` },
              { label: 'Sx — Strong-Axis S',   us: `${s.Sx} in³`, si: `${(s.Sx*IN3_TO_CM3).toFixed(0)} cm³` },
              { label: 'rx — Radius of Gyr.',  us: `${s.rx} in`,  si: `${(s.rx*2.54).toFixed(2)} cm` },
              { label: 'Zx — Plastic Modulus', us: `${s.Zx} in³`, si: `${(s.Zx*IN3_TO_CM3).toFixed(0)} cm³` },
              { label: 'Iy — Weak-Axis I',     us: `${s.Iy} in⁴`, si: `${(s.Iy*IN4_TO_CM4).toFixed(0)} cm⁴` },
              { label: 'Sy — Weak-Axis S',     us: `${s.Sy} in³`, si: `${(s.Sy*IN3_TO_CM3).toFixed(0)} cm³` },
              { label: 'ry — Radius of Gyr.',  us: `${s.ry} in`,  si: `${(s.ry*2.54).toFixed(2)} cm` },
            ].map(row => (
              <tr key={row.label}>
                <td style={tdLabel}>{row.label}</td>
                {showUS && <td style={tdUS}>{row.us}</td>}
                {showSI && <td style={tdSI}>{row.si}</td>}
              </tr>
            ))}
            {s.bf2tf != null && <tr><td style={tdLabel}>bf/2tf (Flange)</td>{showUS && <td style={tdUS}>{s.bf2tf}</td>}{showSI && <td style={tdSI}>—</td>}</tr>}
            {s.htw   != null && <tr><td style={tdLabel}>h/tw (Web)</td>{showUS && <td style={tdUS}>{s.htw}</td>}{showSI && <td style={tdSI}>—</td>}</tr>}
          </tbody>
        </table>
      </div>
    </div>
  )
}

function SectionHeader({ children }) {
  return <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--ac-main)', letterSpacing: '0.07em', textTransform: 'uppercase', marginBottom: 6, paddingBottom: 3, borderBottom: '1px solid var(--bd-subtle)' }}>{children}</div>
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 20, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const inputStyle = { background: 'var(--bg-input)', border: '1px solid var(--bd-subtle)', borderRadius: 6, color: 'var(--tx-primary)', padding: '6px 10px', fontSize: 13 }
const hint       = { padding: '12px 16px', borderRadius: 8, background: 'var(--bg-inset)', border: '1px dashed var(--bd-subtle)', color: 'var(--tx-muted)', fontSize: 13 }
const seriesHead = { fontSize: 10, fontWeight: 700, color: 'var(--ac-main)', letterSpacing: '0.05em', textTransform: 'uppercase', padding: '3px 8px', background: 'var(--bg-inset)', borderRadius: 4, marginBottom: 3 }
const th         = { background: 'var(--bg-inset)', color: 'var(--ac-main)', fontWeight: 600, padding: '6px 10px', textAlign: 'left', borderBottom: '2px solid var(--bd-accent)', fontSize: 12, whiteSpace: 'nowrap' }
const tdLabel    = { padding: '4px 8px', color: 'var(--tx-secondary)', borderBottom: '1px solid var(--bd-subtle)', width: '42%', fontSize: 12 }
const tdUS       = { padding: '4px 8px', fontWeight: 700, color: 'var(--val-pos)', borderBottom: '1px solid var(--bd-subtle)', fontSize: 12 }
const tdSI       = { padding: '4px 8px', fontWeight: 600, color: 'var(--ac-main)', borderBottom: '1px solid var(--bd-subtle)', fontSize: 12 }
